#define LL_IWDG_KR_OFFSET 0x000U
#define LL_IWDG_KR_KEY_POS 0U
#define LL_IWDG_KR_KEY_MSK 0x0000FFFFU

/* IWDG_PR (RM0486 59.7.2) */
#define LL_IWDG_PR_OFFSET 0x004U
#define LL_IWDG_PR_PR_POS 0U
#define LL_IWDG_PR_PR_MSK 0x0000000FU

/* IWDG_RLR (RM0486 59.7.3) */
#define LL_IWDG_RLR_OFFSET 0x008U
#define LL_IWDG_RLR_RL_POS 0U
#define LL_IWDG_RLR_RL_MSK 0x00000FFFU

/* IWDG_SR (RM0486 59.7.4) */
#define LL_IWDG_SR_OFFSET 0x00CU
#define LL_IWDG_SR_EWIF_POS 15U
#define LL_IWDG_SR_EWIF_MSK 0x00008000U
#define LL_IWDG_SR_ONF_POS 8U
#define LL_IWDG_SR_ONF_MSK 0x00000100U
#define LL_IWDG_SR_EWU_POS 3U
